/* FRAGMENTS Obsidian theme.
   The diary rules below are bundled from fragments-studio.css so the theme
   can render archive notes and film callouts on its own. */

body {
  --radius-s: 3px;
}

body.theme-light {
  --background-primary: var(--fragments-bg);
  --background-primary-alt: var(--fragments-surface);
  --background-secondary: var(--fragments-sidebar);
  --background-secondary-alt: #e8e4da;
  --background-modifier-border: var(--fragments-border);
  --background-modifier-hover: #eae5dc;
  --text-normal: var(--fragments-text);
  --text-muted: var(--fragments-muted);
  --text-faint: #75716a;
  --link-color: var(--fragments-accent);
  --link-color-hover: #604123;
  --link-external-color: var(--fragments-accent);
  --text-selection: #ded0b5;
}

body.theme-dark {
  --background-primary: var(--fragments-bg);
  --background-primary-alt: var(--fragments-surface);
  --background-secondary: var(--fragments-sidebar);
  --background-secondary-alt: #191b1e;
  --background-modifier-border: var(--fragments-border);
  --background-modifier-hover: #24272a;
  --text-normal: var(--fragments-text);
  --text-muted: var(--fragments-muted);
  --text-faint: #8f8c83;
  --link-color: var(--fragments-accent);
  --link-color-hover: #e5c994;
  --link-external-color: var(--fragments-accent);
  --text-selection: #4d402a;
}

.workspace :is(button, a, input, select, textarea, [tabindex="0"]):focus-visible {
  outline: 2px solid var(--fragments-accent);
  outline-offset: 2px;
}

/* FRAGMENTS · diary typography, film frames and photo layouts.
   All rendered rules opt in via a note class or a callout identifier. */
body.theme-light,
body.theme-dark {
  --fragments-hand: Caveat, "Segoe Print", var(--fragments-literary);
  --fragments-frame: #08090a;
  --fragments-overlay-offset: .65rem;
  --fragments-gallery-gutter: .5rem;
}

/* Reading View and rendered Live Preview. Source Mode keeps the user's editor. */
:is(.markdown-preview-view, .markdown-source-view.is-live-preview):is(.film-diary, .poetic-film, .poetry-note, .photo-essay, .contact-sheet, .letter-note, .philosophy-note, .music-diary, .cinema-review, .minimal-journal, .archive-home, .fragments-gallery, .research-note) {
  --font-monospace: var(--fragments-code);
  --background-primary: var(--fragments-bg);
  --background-primary-alt: var(--fragments-surface);
  --text-normal: var(--fragments-text);
  --text-muted: var(--fragments-muted);
  --text-accent: var(--fragments-accent);
  --link-color: var(--fragments-accent);
  --link-color-hover: var(--fragments-text);
  --link-external-color: var(--fragments-accent);
  --metadata-label-text-color: var(--fragments-muted);
  color: var(--fragments-text);
  background: var(--fragments-bg);
  font-family: var(--font-text);
}
:is(.markdown-preview-view, .markdown-source-view.is-live-preview):is(.film-diary, .poetic-film, .letter-note, .philosophy-note) {
  --fragments-body: var(--fragments-literary);
}
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).poetry-note {
  --fragments-body: var(--fragments-poetry);
  --fragments-width: 33rem;
}
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).letter-note { --fragments-width: 37rem; }
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).minimal-journal { --fragments-width: 41rem; }
:is(.markdown-preview-view, .markdown-source-view.is-live-preview):is(.photo-essay, .contact-sheet, .music-diary, .fragments-gallery) { --fragments-width: 62rem; }
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).cinema-review { --fragments-width: 52rem; }
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).philosophy-note { --fragments-width: 42rem; }
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).research-note {
  --fragments-width: 76rem;
}
:is(.markdown-preview-view, .markdown-source-view.is-live-preview):is(.archive-home, .photo-essay, .film-diary, .poetry-note, .research-note, .fragments-gallery)
  :is(a, button, [tabindex="0"]):focus-visible {
  outline: 2px solid var(--fragments-accent);
  outline-offset: 3px;
}
/* Film frames. Use one image paragraph followed by a blank quote line and a caption. */
.callout:is([data-callout="film"], [data-callout="film-yellow"], [data-callout="film-poetry"], [data-callout="film-overlay"], [data-callout="film-wide"], [data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) {
  --callout-blend-mode: normal;
  --callout-padding: 0;
  --callout-content-padding: 0;
  --callout-border-width: 0px;
  --callout-radius: 2px;
  --callout-content-background: transparent;
  --callout-color: 8, 9, 10;
  --fragments-film-color: var(--fragments-ivory);
  --fragments-film-font: var(--fragments-subtitles);
  --fragments-film-style: normal;
  --fragments-film-fit: contain;
  --fragments-film-offset: var(--fragments-overlay-offset);
  container: fragments-film / inline-size;
  padding: 0;
  margin-block: 1.4rem;
  border: 0;
  border-radius: 2px;
  background: var(--fragments-frame);
  color: var(--fragments-ivory);
  box-shadow: none;
}
.callout:is([data-callout|="film"], [data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-title:not(:has(.callout-fold)) {
  display: none;
}
.callout:is([data-callout|="film"], [data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content {
  padding: 0;
  margin: 0;
  background: transparent;
}
.callout:is([data-callout|="film"], [data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content > p {
  margin: 0;
  padding: .7rem .8rem;
  text-align: center;
  overflow-wrap: anywhere;
  color: var(--fragments-film-color, var(--fragments-ivory));
  font: var(--fragments-film-style, normal) 400 var(--fragments-subtitle-size)/1.43 var(--fragments-film-font, var(--fragments-subtitles));
}
.callout:is([data-callout|="film"], [data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content a {
  color: var(--fragments-ivory);
  text-decoration: underline;
}
.callout:is([data-callout="film"], [data-callout="film-yellow"], [data-callout="film-poetry"], [data-callout="film-overlay"], [data-callout="film-wide"]) > .callout-content > p:has(img) {
  padding: 0;
}
.callout:is([data-callout="film"], [data-callout="film-yellow"], [data-callout="film-poetry"], [data-callout="film-overlay"], [data-callout="film-wide"]) > .callout-content > p:has(img) :is(.image-embed, .external-embed) {
  display: block;
  width: 100%;
  max-width: none;
  line-height: 0;
}
.callout:is([data-callout="film"], [data-callout="film-yellow"], [data-callout="film-poetry"], [data-callout="film-overlay"], [data-callout="film-wide"]) > .callout-content > p img {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  max-height: none;
  margin: 0;
  border-radius: 0;
}
.callout[data-callout="film-yellow"] { --fragments-film-color: var(--fragments-yellow); }
.callout[data-callout="film-poetry"],
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).poetic-film .callout[data-callout="film"] {
  --fragments-film-font: var(--fragments-literary);
  --fragments-film-style: italic;
}
.callout:is([data-callout="film-overlay"], [data-callout="film-yellow"])[data-callout-metadata~="high"] { --fragments-film-offset: 1.75rem; }
.callout:is([data-callout="film-overlay"], [data-callout="film-yellow"])[data-callout-metadata~="flush"] { --fragments-film-offset: 0px; }
@container fragments-film (min-width: 19rem) {
  .callout:is([data-callout="film-overlay"], [data-callout="film-yellow"][data-callout-metadata~="overlay"]) > .callout-content:has(> p:first-child img) {
    display: grid;
  }
  .callout:is([data-callout="film-overlay"], [data-callout="film-yellow"][data-callout-metadata~="overlay"]) > .callout-content:has(> p:first-child img) > p {
    grid-area: 1 / 1;
    min-width: 0;
  }
  .callout:is([data-callout="film-overlay"], [data-callout="film-yellow"][data-callout-metadata~="overlay"]) > .callout-content:has(> p:first-child img) > p:last-child {
    z-index: 1;
    align-self: end;
    margin-block-end: var(--fragments-film-offset);
    padding: .44rem .65rem;
    background: rgb(8 9 10 / .84);
    text-shadow: 0 1px 2px #000;
  }
}

/* Letterbox. Omitting a ratio retains the original image shape. */
.callout[data-callout="film-wide"][data-callout-metadata~="3-2"] { --fragments-ratio: 3 / 2; }
.callout[data-callout="film-wide"][data-callout-metadata~="4-3"] { --fragments-ratio: 4 / 3; }
.callout[data-callout="film-wide"][data-callout-metadata~="16-9"] { --fragments-ratio: 16 / 9; }
.callout[data-callout="film-wide"][data-callout-metadata~="185-100"] { --fragments-ratio: 1.85; }
.callout[data-callout="film-wide"][data-callout-metadata~="239-100"] { --fragments-ratio: 2.39; }
.callout[data-callout="film-wide"][data-callout-metadata~="crop"] { --fragments-film-fit: cover; }
.callout[data-callout="film-wide"] > .callout-content > p img {
  aspect-ratio: var(--fragments-ratio, auto);
  object-fit: var(--fragments-film-fit);
}

/* Contact sheets and sequences. Captions and date/place labels span the row. */
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) {
  --fragments-cols: 2;
  --fragments-film-font: var(--fragments-caption);
}
.callout:is([data-callout="triptych"], [data-callout="contact-sheet"][data-callout-metadata~="three"]) { --fragments-cols: 3; }
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content {
  display: grid;
  grid-template-columns: repeat(var(--fragments-cols), minmax(0, 1fr));
  gap: var(--fragments-gallery-gutter);
  padding: var(--fragments-gallery-gutter);
  counter-reset: fragments-frame;
}
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content > p { grid-column: 1 / -1; }
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content > p:has(> .internal-embed, > img) { display: contents; }
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content > p:has(> .internal-embed, > img) > br { display: none; }
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content > p > :is(.internal-embed, img) {
  display: block;
  position: relative;
  min-width: 0;
  width: 100%;
  margin: 0;
  align-self: start;
}
.callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content > p img {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  max-height: none;
  margin: 0;
  border-radius: 0;
}
.callout[data-callout="contact-sheet"] > .callout-content > p img {
  aspect-ratio: 4 / 3;
  object-fit: contain;
  background: #111315;
}
.callout[data-callout="contact-sheet"][data-callout-metadata~="numbered"] > .callout-content > p > .image-embed { counter-increment: fragments-frame; }
.callout[data-callout="contact-sheet"][data-callout-metadata~="numbered"] > .callout-content > p > .image-embed::after {
  content: counter(fragments-frame, decimal-leading-zero);
  position: absolute;
  inset: .24rem auto auto .26rem;
  background: var(--fragments-frame);
  color: var(--fragments-ivory);
  padding: .13rem .25rem;
  font: .73rem/1 var(--fragments-caption);
  pointer-events: none;
}
@container fragments-film (max-width: 26rem) {
  .callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .callout[data-callout="triptych"] > .callout-content > p > :nth-last-child(1 of :is(.internal-embed, img)):nth-child(odd of :is(.internal-embed, img)) { grid-column: 1 / -1; }
}
@container fragments-film (max-width: 17rem) {
  .callout:is([data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) > .callout-content { grid-template-columns: minmax(0, 1fr); }
}

/* Editorial index. Native links and embedded Bases are interactive. */
:is(.markdown-preview-view, .markdown-source-view.is-live-preview).archive-home {
  --fragments-width: 66rem;
  --h1-size: clamp(2.9rem, 2rem + 5vw, 6.4rem);
  --h1-line-height: .93;
  --h2-size: 1.85rem;
}
.markdown-preview-view.archive-home .inline-title { display: none; }
.markdown-preview-view.archive-home .el-h1 > h1 {
  margin: .3em 0 .14em;
  letter-spacing: .025em;
  line-height: .95;
}
.markdown-preview-view.archive-home .el-h1 + .el-p > p {
  margin: .4rem 0 1.35rem;
  color: var(--fragments-muted);
  font: italic 1.23rem/1.4 var(--fragments-literary);
}
.archive-home .callout[data-callout="archive-hero"] {
  --callout-padding: 0;
  --callout-content-padding: 0;
  padding: 0;
  border: 0;
  border-radius: 2px;
  background: var(--fragments-frame);
}
.archive-home .callout:is([data-callout="archive-hero"], [data-callout="archive-index"]) > .callout-title { display: none; }
.archive-home .callout[data-callout="archive-hero"] > .callout-content { padding: 0; }
.archive-home .callout[data-callout="archive-hero"] .image-embed { display: block; line-height: 0; max-width: none; }
.archive-home .callout[data-callout="archive-hero"] p { margin: 0; }
.archive-home .callout[data-callout="archive-hero"] img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 2.5;
  object-fit: cover;
  object-position: center 47%;
  border-radius: 0;
  margin: 0;
}
.archive-home .callout[data-callout="archive-index"] {
  --callout-padding: 0;
  --callout-content-padding: 0;
  border: 0;
  border-block: 1px solid var(--fragments-border);
  border-radius: 0;
  background: transparent;
  padding: .65rem 0;
}
.archive-home .callout[data-callout="archive-index"] > .callout-content > p {
  display: flex;
  flex-wrap: wrap;
  gap: .35rem 1rem;
  margin: 0;
}
.archive-home .callout[data-callout="archive-index"] > .callout-content > p > br { display: none; }
.archive-home .callout[data-callout="archive-index"] a {
  padding: .15rem 0;
  color: var(--fragments-accent);
  text-decoration: none;
  font: 550 .88rem/1.4 var(--fragments-interface);
}
.archive-home .callout[data-callout="archive-index"] a:hover { text-decoration: underline; }
:is(.archive-home, .fragments-gallery) .bases-embed {
  --background-primary: var(--fragments-bg);
  --background-secondary: var(--fragments-surface);
  --bases-cards-background: var(--fragments-surface);
  --bases-cards-label-color: var(--fragments-muted);
  --bases-cards-border-color: var(--fragments-border);
  --bases-cards-border-radius: 2px;
}
@media (forced-colors: active) {
  .callout:is([data-callout|="film"], [data-callout="contact-sheet"], [data-callout="diptych"], [data-callout="triptych"]) {
    border: 1px solid CanvasText;
  }
  .callout:is([data-callout="film-overlay"], [data-callout="film-yellow"]) > .callout-content > p:last-child {
    color: CanvasText;
    background: Canvas;
  }
}

/* Colored folders. Branches inherit the color of their top-level folder. */
.nav-files-container {
  --fragments-folder-rose: #c97a86;
  --fragments-folder-apricot: #d6977c;
  --fragments-folder-gold: #e9c989;
  --fragments-folder-moss: #a8bd95;
  --fragments-folder-teal: #8cb9b3;
  --fragments-folder-blue: #9ab1cb;
  --fragments-folder-lilac: #b5a6cb;
  --fragments-folder-tint: var(--fragments-folder-blue);
}

.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="%SystemDrive%"]),
.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="07_Decision_Log"]) {
  --fragments-folder-tint: var(--fragments-folder-rose);
}

.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="01_Daily_Notes"]),
.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="09_Stakeholders"]) {
  --fragments-folder-tint: var(--fragments-folder-apricot);
}

.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="02_BA_Knowledge"]),
.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="10_Reports"]) {
  --fragments-folder-tint: var(--fragments-folder-gold);
}

.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="03_Projects"]),
.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="11_PROJECT_MANAGEMENT"]) {
  --fragments-folder-tint: var(--fragments-folder-moss);
}

.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="08_Meeting_Notes"]),
.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="99_Attachments"]) {
  --fragments-folder-tint: var(--fragments-folder-teal);
}

.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="Fragments"]),
.nav-files-container .nav-folder:has(> .nav-folder-title[data-path="Excalidraw"]) {
  --fragments-folder-tint: var(--fragments-folder-lilac);
}

/* Obsidian gives each row a vault-relative data-path. Top-level paths have no slash. */
.nav-files-container .nav-folder-title[data-path]:not([data-path=""]):not([data-path*="/"]) {
  color: var(--fragments-folder-ink);
  font-weight: 600;
}

.nav-files-container .nav-folder-title[data-path]:not([data-path=""]):not([data-path*="/"]) :is(.collapse-icon, .collapse-icon svg) {
  color: inherit;
}

.nav-files-container .nav-folder-title[data-path]:not([data-path=""]):not([data-path*="/"]):hover {
  color: var(--fragments-folder-ink);
}

.nav-files-container .nav-folder-title[data-path]:not([data-path=""]):not([data-path*="/"]):focus-visible {
  outline: 2px solid var(--fragments-folder-ink);
  outline-offset: -3px;
}

/* Semantic callout colors */
body.theme-light {
  --fragments-callout-note: 60, 83, 125;
  --fragments-callout-abstract: 99, 68, 132;
  --fragments-callout-info: 23, 91, 115;
  --fragments-callout-todo: 40, 95, 148;
  --fragments-callout-tip: 26, 104, 83;
  --fragments-callout-success: 54, 101, 51;
  --fragments-callout-question: 118, 95, 30;
  --fragments-callout-warning: 145, 83, 29;
  --fragments-callout-failure: 146, 63, 59;
  --fragments-callout-danger: 156, 43, 64;
  --fragments-callout-bug: 126, 59, 105;
  --fragments-callout-example: 95, 79, 145;
  --fragments-callout-quote: 76, 86, 92;
}

body.theme-dark {
  --fragments-callout-note: 158, 183, 224;
  --fragments-callout-abstract: 202, 171, 233;
  --fragments-callout-info: 130, 199, 218;
  --fragments-callout-todo: 135, 187, 232;
  --fragments-callout-tip: 113, 204, 176;
  --fragments-callout-success: 155, 204, 145;
  --fragments-callout-question: 229, 200, 126;
  --fragments-callout-warning: 239, 175, 122;
  --fragments-callout-failure: 235, 147, 138;
  --fragments-callout-danger: 246, 143, 164;
  --fragments-callout-bug: 230, 155, 211;
  --fragments-callout-example: 191, 174, 235;
  --fragments-callout-quote: 178, 192, 199;
}

/* Native callout families keep their original icons, fold controls, and aliases. */
.callout:is([data-callout="note"]) {
  --callout-color: var(--fragments-callout-note);
}

.callout:is([data-callout="abstract"], [data-callout="summary"], [data-callout="tldr"]) {
  --callout-color: var(--fragments-callout-abstract);
}

.callout:is([data-callout="info"]) {
  --callout-color: var(--fragments-callout-info);
}

.callout:is([data-callout="todo"]) {
  --callout-color: var(--fragments-callout-todo);
}

.callout:is([data-callout="tip"], [data-callout="hint"], [data-callout="important"]) {
  --callout-color: var(--fragments-callout-tip);
}

.callout:is([data-callout="success"], [data-callout="check"], [data-callout="done"]) {
  --callout-color: var(--fragments-callout-success);
}

.callout:is([data-callout="question"], [data-callout="help"], [data-callout="faq"]) {
  --callout-color: var(--fragments-callout-question);
}

.callout:is([data-callout="warning"], [data-callout="caution"], [data-callout="attention"]) {
  --callout-color: var(--fragments-callout-warning);
}

.callout:is([data-callout="failure"], [data-callout="fail"], [data-callout="missing"]) {
  --callout-color: var(--fragments-callout-failure);
}

.callout:is([data-callout="danger"], [data-callout="error"]) {
  --callout-color: var(--fragments-callout-danger);
}

.callout:is([data-callout="bug"]) {
  --callout-color: var(--fragments-callout-bug);
}

.callout:is([data-callout="example"]) {
  --callout-color: var(--fragments-callout-example);
}

.callout:is([data-callout="quote"], [data-callout="cite"]) {
  --callout-color: var(--fragments-callout-quote);
}

.callout:is(
  [data-callout="note"],
  [data-callout="abstract"], [data-callout="summary"], [data-callout="tldr"],
  [data-callout="info"],
  [data-callout="todo"],
  [data-callout="tip"], [data-callout="hint"], [data-callout="important"],
  [data-callout="success"], [data-callout="check"], [data-callout="done"],
  [data-callout="question"], [data-callout="help"], [data-callout="faq"],
  [data-callout="warning"], [data-callout="caution"], [data-callout="attention"],
  [data-callout="failure"], [data-callout="fail"], [data-callout="missing"],
  [data-callout="danger"], [data-callout="error"],
  [data-callout="bug"],
  [data-callout="example"],
  [data-callout="quote"], [data-callout="cite"]
) {
  --callout-blend-mode: normal;
  --callout-radius: 6px;
  border: 1px solid rgba(var(--callout-color), .24);
  border-inline-start: 3px solid rgba(var(--callout-color), .75);
  background-color: rgba(var(--callout-color), .09);

  & > .callout-title {
