.markdown-rendered pre { overflow-x: auto; }
.metadata-container { --metadata-label-text-color: var(--fragments-text-muted); font-family: var(--fragments-interface); }
.metadata-container .metadata-property-key-input { font-family: var(--fragments-code); }

.workspace-tab-header { --tab-text-color: var(--fragments-text-secondary); }
.workspace-tab-header.is-active { box-shadow: inset 0 -1px var(--fragments-accent); }
.workspace-tab-header-inner-title { font-weight: var(--tab-font-weight); }
.titlebar-text, .view-header-title { font-weight: 600; }
.view-header-breadcrumb { color: var(--fragments-text-muted); font-size: var(--font-ui-small); }
:is(.nav-file-title, .nav-folder-title) { min-height: 26px; }
:is(.nav-file-title, .nav-folder-title).is-active { box-shadow: inset 2px 0 var(--fragments-accent); }
.search-result-file-match { line-height: 1.55; }
.search-result-file-match .search-result-file-matched-text { background: var(--text-selection); }
.mod-settings .setting-item-description { line-height: 1.5; }

.nav-files-container {
  --fragments-folder-ink: var(--fragments-text-primary);
  --fragments-guide-mix: var(--fragments-border);
  --nav-indentation-guide-width: 1px;
}
.nav-files-container .nav-folder-title[data-path]:not([data-path=""]):not([data-path*="/"]) {
  border-radius: 3px;
  background-color: color-mix(in srgb, var(--fragments-folder-tint) var(--fragments-folder-intensity, var(--fragments-folder-default, 13%)), transparent);
  box-shadow: inset 2px 0 color-mix(in srgb, var(--fragments-folder-tint) 65%, var(--fragments-border));
}
.nav-files-container .nav-folder-title[data-path]:not([data-path=""]):not([data-path*="/"]):hover {
  background-color: color-mix(in srgb, var(--fragments-folder-tint) calc(var(--fragments-folder-intensity, var(--fragments-folder-default, 13%)) + 7%), transparent);
}
.nav-files-container .nav-folder:not(.mod-root) > .nav-folder-children {
  border-inline-start-color: color-mix(in srgb, var(--fragments-folder-tint) calc(var(--fragments-folder-intensity, var(--fragments-folder-default, 13%)) * 2.5), var(--fragments-border));
}

/* Native Canvas preserves colored nodes, group fills, focus, and drag controls. */
.canvas-node:not(.canvas-node-group, .is-themed, [data-shape]) .canvas-node-container {
  background-color: var(--fragments-canvas-surface);
  border-radius: 5px;
}
.canvas-node:not(.canvas-node-group, .is-themed, .is-selected, .is-focused, [data-shape]) .canvas-node-container {
  border-color: var(--fragments-canvas-border);
}
.canvas-node-label, .canvas-group-label { font-family: var(--fragments-interface); font-weight: 600; }
.canvas-node-content,
.canvas-node-content :is(.markdown-preview-view, .markdown-source-view) {
  --font-text-size: calc(14.5px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --h1-size: calc(26px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --h2-size: calc(22px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --h3-size: calc(18px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --h4-size: calc(16px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --h5-size: calc(14px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --h6-size: calc(13px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  --inline-title-size: var(--h1-size);
  --line-height-normal: 1.48;
  --p-spacing: .7em;
  --fragments-quote-font: var(--fragments-prose);
  --file-line-width: 100%;
}
.canvas-node-content.markdown-embed > .markdown-embed-content > .markdown-preview-view,
.canvas-node-content .markdown-source-view .cm-contentContainer {
  padding-inline: calc(var(--fragments-canvas-padding, var(--fragments-canvas-default-padding, 16px)) * var(--fragments-canvas-padding-factor, 1));
}
.canvas-node-content .markdown-rendered :is(td, th) {
  font-size: calc(13px * var(--fragments-canvas-scale, 1) * var(--fragments-canvas-density, 1));
  padding: var(--fragments-cell-padding, 6px) .65em;
}
.fragments-compact-canvas { --fragments-canvas-default-padding: 10px; --fragments-canvas-density: .92; }

.callout:is([data-callout="note"], [data-callout="abstract"], [data-callout="summary"], [data-callout="tldr"], [data-callout="info"], [data-callout="todo"], [data-callout="tip"], [data-callout="hint"], [data-callout="important"], [data-callout="success"], [data-callout="check"], [data-callout="done"], [data-callout="question"], [data-callout="help"], [data-callout="faq"], [data-callout="warning"], [data-callout="caution"], [data-callout="attention"], [data-callout="failure"], [data-callout="fail"], [data-callout="missing"], [data-callout="danger"], [data-callout="error"], [data-callout="bug"], [data-callout="example"], [data-callout="quote"], [data-callout="cite"]) {
  --callout-radius: 4px;
  --callout-padding: var(--fragments-callout-inset, .75em) .88em;
  --callout-icon-size: 15px;
  border-inline-start-width: 2px;
  background-color: rgba(var(--callout-color), .065);
}
.callout:is([data-callout="note"], [data-callout="abstract"], [data-callout="summary"], [data-callout="tldr"], [data-callout="info"], [data-callout="todo"], [data-callout="tip"], [data-callout="hint"], [data-callout="important"], [data-callout="success"], [data-callout="check"], [data-callout="done"], [data-callout="question"], [data-callout="help"], [data-callout="faq"], [data-callout="warning"], [data-callout="caution"], [data-callout="attention"], [data-callout="failure"], [data-callout="fail"], [data-callout="missing"], [data-callout="danger"], [data-callout="error"], [data-callout="bug"], [data-callout="example"], [data-callout="quote"], [data-callout="cite"]) > .callout-title,
.callout[data-callout^="ppj-"] > .callout-title {
  font-family: var(--fragments-interface);
  font-weight: 650;
  line-height: 1.4;
}
.callout:is([data-callout="ppj-metrics"], [data-callout="ppj-columns"], [data-callout="ppj-roadmap"], [data-callout="ppj-priorities"]) { --callout-radius: 5px; }
.callout:is([data-callout="ppj-stat"], [data-callout="ppj-flow"], [data-callout="ppj-meter"]) { border-radius: 4px; }
.callout[data-callout="ppj-metrics"] { container: fragments-metrics / inline-size; }
@container fragments-metrics (max-width: 18rem) {
  .callout[data-callout="ppj-metrics"] > .callout-content { grid-template-columns: 1fr; }
}
.callout[data-callout="ppj-roadmap"] table { min-width: 23em; }

@media (max-width: 740px) {
  :is(.markdown-preview-view, .markdown-source-view) :is(.inline-title:not([data-level])) {
    font-size: min(var(--inline-title-size), 36px);
  }
}


